function parsePlace(body, isPO3) {
  const br = new BR(body);
  const flags = br.ub(8);
  const hasClipActions = !!(flags & 0x80),
    hasClipDepth = !!(flags & 0x40),
    hasName = !!(flags & 0x20),
    hasRatio = !!(flags & 0x10),
    hasColor = !!(flags & 0x08),
    hasMatrix = !!(flags & 0x04),
    hasChar = !!(flags & 0x02),
    move = !!(flags & 0x01);
  // PlaceObject3 has its second flag byte BEFORE depth.
  const f2 = isPO3 ? br.ub(8) : 0;
  const depth = br.bytes(2);
  const p = { depth, isPO3 };
  if (isPO3) {
    const hasOpaqueBg = !!(f2 & 0x40),
      hasVisible = !!(f2 & 0x20),
      hasImage = !!(f2 & 0x10),
      hasClassName = !!(f2 & 0x08),
      hasCache = !!(f2 & 0x04),
      hasBlend = !!(f2 & 0x02),
      hasFilters = !!(f2 & 0x01);
    if (hasClassName || (hasImage && hasChar)) p.className = br.string();
    if (hasChar) p.charId = br.bytes(2);
    if (hasMatrix) p.matrix = matrix(br);
    if (hasColor) p.color = readCxFormWithAlpha(br);
    if (hasRatio) p.ratio = br.bytes(2);
    if (hasName) p.name = br.string();
    if (hasClipDepth) p.clipDepth = br.bytes(2);
    if (hasFilters) p.filters = readFilterList(br);
    if (hasBlend) p.blendMode = br.bytes(1);
    if (hasCache) p.cacheAsBitmap = br.bytes(1);
    if (hasOpaqueBg) br.bytes(4); // SWF11+ — not expected in v10
    if (hasVisible) {
      br.bytes(1);
      br.bytes(1);
    } // SWF11+
    if (hasClipActions) skipClipActions(br);
    return p;
  }
  if (hasChar) p.charId = br.bytes(2);
  if (hasMatrix) p.matrix = matrix(br);
  if (hasColor) p.color = readCxFormWithAlpha(br);
  if (hasRatio) p.ratio = br.bytes(2);
  if (hasName) p.name = br.string();
  if (hasClipDepth) p.clipDepth = br.bytes(2);
  if (hasClipActions) skipClipActions(br);
  return p;
}

function readCxFormWithAlpha(br) {
  const hasAdd = br.ub(1),
    hasMult = br.ub(1);
  const n = br.ub(4);
  const mult = [1, 1, 1, 1],
    add = [0, 0, 0, 0];
  if (hasMult) for (let i = 0; i < 4; i++) mult[i] = br.sb(n) / 256;
  if (hasAdd) for (let i = 0; i < 4; i++) add[i] = br.sb(n);
  br.align();
  return { mult, add };
}

import type { DisplayPlacement, SpriteInfo } from './asset-pack';
const identity = { a: 1, b: 0, c: 0, d: 1, tx: 0, ty: 0 };

/** Retained SWF depths, shared by browser artwork and numeric simulation poses. */
export function buildDisplayList(sprite: SpriteInfo, age: number): DisplayPlacement[] {
  const frame = ((Math.max(1, Math.floor(age)) - 1) % sprite.frameCount) + 1;
  const list = new Map<number, DisplayPlacement>();
  for (const p of sprite.placements) {
    if (p.frame > frame) break;
    if (p.remove) list.delete(p.depth);
    else {
      const old = list.get(p.depth),
        charId = p.charId ?? old?.charId;
      if (charId !== undefined)
        list.set(p.depth, {
          ...old,
          ...p,
          charId,
          matrix: p.matrix ?? old?.matrix ?? identity,
          bornFrame: p.charId !== undefined ? p.frame : (old?.bornFrame ?? p.frame),
        });
    }
  }
  return [...list.values()].sort((a, b) => a.depth - b.depth);
}
